/* ---------- Composants réels ---------- */
function Snap({ label, onShot, kind = "soft", small = true, full }) {
  const [id] = useState(() => "snap-" + Math.random().toString(36).slice(2, 8));
  return <><input id={id} type="file" accept="image/*" capture="environment" style={{ display: "none" }} onChange={(e) => { const f = e.target.files && e.target.files[0]; if (f) onShot({ url: URL.createObjectURL(f), name: f.name, size: f.size, at: now() }); e.target.value = ""; }} /><Btn small={small} full={full} kind={kind} onClick={() => document.getElementById(id).click()}>{label}</Btn></>;
}
async function sha256(blob) { try { const buf = await blob.arrayBuffer(); const h = await crypto.subtle.digest("SHA-256", buf); return Array.from(new Uint8Array(h)).map((b) => b.toString(16).padStart(2, "0")).join(""); } catch { return null; } }

/* Mesures en direct : netteté (variance du laplacien), lumière (luminance moyenne), stabilité (différence entre images) */
function useQuality(videoEl, active) {
  const [q, setQ] = useState({ sharp: null, light: null, motion: null });
  const prev = useRef(null);
  useEffect(() => { if (!videoEl || !active) return; const cv = document.createElement("canvas"); const W = 96, H = 72; cv.width = W; cv.height = H; const ctx = cv.getContext("2d", { willReadFrequently: true }); const it = setInterval(() => { try { ctx.drawImage(videoEl, 0, 0, W, H); const d = ctx.getImageData(0, 0, W, H).data; const g = new Float32Array(W * H); let sum = 0; for (let i = 0; i < W * H; i++) { const v = 0.299 * d[i * 4] + 0.587 * d[i * 4 + 1] + 0.114 * d[i * 4 + 2]; g[i] = v; sum += v; } const light = sum / (W * H); let lap = 0, n = 0; for (let y = 1; y < H - 1; y++) for (let x = 1; x < W - 1; x++) { const i = y * W + x; const l = 4 * g[i] - g[i - 1] - g[i + 1] - g[i - W] - g[i + W]; lap += l * l; n++; } const sharp = lap / n; let motion = 0; if (prev.current) { for (let i = 0; i < W * H; i += 3) motion += Math.abs(g[i] - prev.current[i]); motion = motion / (W * H / 3); } prev.current = g; setQ({ sharp, light, motion }); } catch {} }, 400); return () => clearInterval(it); }, [videoEl, active]);
  return q;
}
