  const resetSeller = () => { setCstep(0); setDocs({}); setPieces({}); setVideos({}); setVidIdx(null); setSimule(false); setDecl({}); setDeclIdx(0); setRecap(false); setPublished(false); setSent(null); setRib(null); setBadge(false); setForfait(params.get("paid") ? "demande" : null); };
  const openReport = () => { const p = resolve(q); if (p.length < 4) return; setPlate(p); setScreen("loading"); };
  const startTx = (veh, pl) => setTx({ v: veh, plate: pl, status: "open", timeline: [{ t: now(), l: "Registre consulté par l'acheteur" }, { t: now(), l: "L'acheteur demande un rendez-vous" }], buyerVerified: false, rdv: null, rdvDraft: {}, contact: "none", session: null, exam: null, price: { ann: veh.prix, proposed: "", cb: false, cs: false, version: 1 }, contract: { read: false, cb: false, cs: false }, pay: { status: "none" }, remise: { km: "", keys: 2, cg: null, docs: {}, ab: false, as: false }, after: {} });
  const nextStep = (t) => !t ? null : t.status === "stopped" ? ["Transaction arrêtée", null] : !t.buyerVerified ? ["Vérifier mon identité", "buyerId"] : !t.rdv ? ["Organiser la rencontre", "rdv"] : !t.session ? ["Je suis avec le vendeur", "dayj"] : !t.exam ? ["Vérifier la voiture ensemble", "dayj"] : !(t.price.cb && t.price.cs) ? ["Fixer le prix", "price"] : !(t.contract.cb && t.contract.cs) ? ["Signer le contrat", "contract"] : t.pay.status !== "received" ? ["Payer", "pay"] : !(t.remise.ab && t.remise.as) ? ["Remettre le véhicule", "remise"] : ["Voir mon dossier", "done"];
  useEffect(() => { if (screen === "loading") { const t = setTimeout(() => { if (REGISTRE[plate]) { setDetail(false); setScreen("report"); } else { setNoneFrom("consult"); setScreen("none"); } }, 900); return () => clearTimeout(t); } }, [screen, plate]);
  useEffect(() => { if (screen === "certify" && plate) saveDraft({ plate, cstep, forfait, at: Date.now(), marque: known.marque, modele: known.modele }); if (screen === "certify" && published) saveDraft(null); }, [screen, cstep, published]); // eslint-disable-line
  useEffect(() => { if (gate) return; const q0 = params.get("q"); if (params.get("mode") === "certify" && screen === "home") { if (q0 && resolve(q0).length >= 4) { setQ(q0); setPlate(resolve(q0)); setFound(REGISTRE[resolve(q0)] || null); setScreen("plate"); } else setScreen("plate"); } else if (q0 && screen === "home" && !plate) { const p = resolve(q0); if (p.length >= 4) { setPlate(p); setScreen("loading"); } } if (params.get("ask") && screen === "home" && !plate) { setPlate("AA-000-AA"); setNoneFrom("home"); setScreen("none"); } }, [gate]); // eslint-disable-line
