          {draft && !published ? <Card style={{ marginTop: 8 }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}><div><div style={{ fontSize: 17, fontWeight: 800, color: T.ink }}>{draft.marque} {draft.modele}</div><div style={{ fontSize: 13.5, color: T.sub, marginTop: 2 }}>Registre à terminer · {["environ 5 min", "environ 3 min", "environ 2 min", "moins d'une minute"][Math.min(3, draft.cstep || 0)]} restantes</div></div><Btn small onClick={() => { setPlate(draft.plate); setCstep(draft.cstep || 0); setForfait(draft.forfait || null); setScreen("certify"); }}>Continuer</Btn></div></Card>
          : published ? <Card style={{ marginTop: 8 }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}><div><div style={{ fontSize: 17, fontWeight: 800, color: T.ink }}>{known.marque} {known.modele}</div><div style={{ fontSize: 13.5, color: T.sub, marginTop: 2 }}>{known.num} · Registre publié · 23 consultations</div></div><Btn small kind="soft" onClick={() => { setCstep(4); setScreen("certify"); }}>Ouvrir</Btn></div>
            <div style={{ fontSize: 11.5, letterSpacing: .8, textTransform: "uppercase", color: T.mute, fontWeight: 800, marginTop: 16 }}>Acheteurs intéressés</div>
            {[["Julien M.", true, "Rendez-vous samedi · 14 h", "Transaction ouverte", true], ["Sophie P.", true, "A demandé une actualisation", null, false], ["Thomas R.", false, "A consulté le Registre", null, false]].map(([n, ok, s, tag, open]) => <div key={n} style={{ padding: "12px 0", borderTop: `1px solid ${T.line}` }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}><div><div style={{ fontSize: 16, fontWeight: 700, color: T.ink }}>{n} {ok && <span style={{ color: T.greenD, fontSize: 13, fontWeight: 800 }}>✓ Identité vérifiée</span>}</div><div style={{ fontSize: 13.5, color: T.sub, marginTop: 2 }}>{s}</div></div>{tag && <Kick tone="green">{tag}</Kick>}</div>{open && <div style={{ display: "flex", gap: 8, marginTop: 10 }}><Btn small kind="soft" onClick={() => {}}>Appeler {n.split(" ")[0]}</Btn><Btn small kind="soft" onClick={() => {}}>SMS</Btn><span style={{ ...M, fontSize: 13, color: T.mute, alignSelf: "center" }}>06 •• •• •• 42</span></div>}</div>)}
            <P style={{ fontSize: 13, color: T.mute, marginTop: 10 }}>Le Registre de la voiture est commun à tous les acheteurs ; une seule transaction à la fois peut entrer en phase contrat et paiement.</P></Card>
          : <Card style={{ marginTop: 8, background: T.bg, boxShadow: "none" }}><P style={{ fontSize: 14.5 }}>Aucun Registre de vente pour l'instant.</P><div style={{ marginTop: 10 }}><Btn small onClick={() => { setQ(""); setFound(null); setScreen("plate"); }}>Créer le Registre de ma voiture</Btn></div></Card>}
          <div style={{ fontSize: 12, letterSpacing: .8, textTransform: "uppercase", color: T.mute, fontWeight: 800, marginTop: 22 }}>Mes achats</div>
          {tx ? <Card style={{ marginTop: 8 }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}><div><div style={{ fontSize: 17, fontWeight: 800, color: T.ink }}>{tx.v.marque} {tx.v.modele}</div><div style={{ fontSize: 13.5, color: T.sub, marginTop: 2 }}>{tx.v.num} · {nextStep(tx)[0]}</div></div><Btn small kind="soft" onClick={() => setScreen("hub")}>Ouvrir</Btn></div></Card>
          : <Card style={{ marginTop: 8, background: T.bg, boxShadow: "none" }}><P style={{ fontSize: 14.5 }}>Aucun achat en cours.</P></Card>}
          {requests.length > 0 && <><div style={{ fontSize: 12, letterSpacing: .8, textTransform: "uppercase", color: T.mute, fontWeight: 800, marginTop: 22 }}>Mes demandes</div>{requests.map((r, i) => <Card key={i} style={{ marginTop: 8 }}><div style={{ fontSize: 16, fontWeight: 800, color: T.ink }}>Registre {r}</div><div style={{ fontSize: 13.5, color: T.amber, fontWeight: 700, marginTop: 2 }}>En attente du vendeur</div></Card>)}</>}
